/* Includes */
#include <errno.h>
#include <stdio.h>

/* Variables */
extern int errno;

/* Functions */

/**
 _sbrk
 Increase program data space. Malloc and related functions depend on this
**/
void *_sbrk(int incr)
{
	extern char end asm("end");
	extern char _estack;	/* top of RAM, MSP stack top */
	static char *heap_end;
	char *prev_heap_end;

	if (heap_end == 0)
		heap_end = &end;

	prev_heap_end = heap_end;
	/* FreeRTOS task stacks live inside the ucHeap array below `end`, so the
	   SP-based check newlib defaults to would always fail in task context.
	   Bound the heap by the RAM top instead, keeping a margin for the MSP
	   (ISR) stack. */
	if (heap_end + incr > &_estack - 0x400)
	{
		errno = ENOMEM;
		return (void *)-1;
	}

	heap_end += incr;

	return (void *)prev_heap_end;
}

